import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group: ThreeGroup } = THREE;

  // Main container
  const root = new ThreeGroup();

  // ---------- Backdrop ----------
  const gradientMat = new MeshStandardNodeMaterial();
  gradientMat.colorNode = mix(color('#0b0b10'), color('#13131a'), uv().y);
  gradientMat.roughness = 0.9;
  gradientMat.metalness = 0.0;
  const backdrop = new Mesh(new PlaneGeometry(7, 5.5), gradientMat);
  backdrop.position.z = -1.5;
  root.add(backdrop);

  // ---------- Hero Text ----------
  const heroGroup = new ThreeGroup();
  heroGroup.position.y = 0.4;

  const heroString = 'TIME, MACHINED.';
  const words = heroString.split(' ');
  const zOffsets = [0.12, -0.12];
  const xOffsets = [-1.2, 1.2]; // simple manual spacing

  words.forEach((w, i) => {
    const txt = ctx.fontAtlas.createText(w, {
      fontSize: 124,
      color: '#16161d',
      align: 'left',
    });
    txt.position.set(xOffsets[i] || 0, 0, zOffsets[i] ?? 0);
    heroGroup.add(txt);
  });

  root.add(heroGroup);

  // ---------- Accent Underline ----------
  const underlineGeom = new PlaneGeometry(2.6, 0.045);
  // shift geometry so left edge is the pivot
  underlineGeom.translate(1.3, 0, 0);
  const underlineMat = new MeshStandardNodeMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.2,
    roughness: 0.5,
    metalness: 0.0,
  });
  const underline = new Mesh(underlineGeom, underlineMat);
  underline.scale.set(0, 1, 1);
  // anchor left under first word
  underline.position.set(xOffsets[0] ?? 0, heroGroup.position.y - 0.05, 0);
  root.add(underline);

  // ---------- Subhead ----------
  const subhead = ctx.fontAtlas.createText(
    'Every calibre begins as a solid billet.',
    {
      fontSize: 40,
      color: '#16161d',
      align: 'center',
    }
  );
  subhead.position.set(0, -0.65, 0);
  root.add(subhead);

  // ---------- Caption ----------
  const caption = ctx.fontAtlas.createText(
    'NOVA ATELIER / CALIBRE PROGRAM',
    {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'center',
    }
  );
  caption.position.set(0, 1.15, 0);
  root.add(caption);

  // ---------- Animations ----------
  const timelines = [];

  // Cinematic primitives
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((p) => {
      const h = ctx.primitives[p.name](heroGroup, p.params);
      primitiveHandles.push(h);
    });
  }

  // Attach post‑kinetic actions (underline & settle)
  const kineticHandle = primitiveHandles.find((h) => h && h.timeline);
  if (kineticHandle && kineticHandle.timeline) {
    kineticHandle.timeline.eventCallback('onComplete', () => {
      const tl = gsap.timeline();

      // Underline reveal
      tl.to(
        underline.scale,
        {
          x: 1,
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
          delay: 0.12,
        },
        0
      );

      // Weighted settle on hero group
      tl.fromTo(
        heroGroup.scale,
        { x: 1.04, y: 1.04, z: 1.04 },
        {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.9,
          ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        },
        0
      );

      timelines.push(tl);
    });
  }

  // Subhead fade‑up
  const subheadTl = gsap.timeline();
  subheadTl.from(
    subhead.position,
    {
      y: subhead.position.y + 0.2,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );
  // Ensure text material is transparent for opacity animation
  if (subhead.material) {
    subhead.material.transparent = true;
    subhead.material.opacity = 0;
    subheadTl.to(
      subhead.material,
      {
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      0
    );
  }
  timelines.push(subheadTl);

  // ---------- Cleanup ----------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Kill GSAP timelines
    timelines.forEach((t) => t.kill());

    // Cleanup primitives
    primitiveHandles.forEach((h) => {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    });

    // Dispose materials and geometries
    if (gradientMat && typeof gradientMat.dispose === 'function')
      gradientMat.dispose();
    if (underlineMat && typeof underlineMat.dispose === 'function')
      underlineMat.dispose();
    if (backdrop.geometry && typeof backdrop.geometry.dispose === 'function')
      backdrop.geometry.dispose();
    if (underline.geometry && typeof underline.geometry.dispose === 'function')
      underline.geometry.dispose();
  };

  return root;
}
